INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020022, 302, "nyx_cmn_03", 0.2, "", 3, "", "", 111031, 1, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020023, 302, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", "", "", 11, "", "", 111031, 10, "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (13020024, 302, "", "", "", 91, "", "", 0, "", "");
